INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1207, 3, 0.0, 1, 2, 0, "vo_minigame_1012_correct_131", -1, 2, 11120701, 0, "巻き返すわよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1301, 0, 0.0, 1, 2, 0, "vo_minigame_1012_incorrect_107", 0, 2, 11130101, 0, "切り替えて！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1301, 0, 0.0, 1, 9, 0, "vo_minigame_1012_incorrect_108", 0, 9, 11130102, 0, "こんなこともあるわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1301, 0, 0.0, 1, 4, 0, "vo_minigame_1012_incorrect_109", 0, 4, 11130103, 0, "それじゃダメよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1302, 20000, 0.0, 1, 4, 0, "vo_minigame_1012_incorrect_116", -1, 4, 11130201, 0, "タイムアップよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1302, 20000, 0.0, 1, 5, 0, "vo_minigame_1012_incorrect_117", -1, 5, 11130202, 0, "いや答えなさいよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1303, 0, 0.01, 1, 3, 0, "vo_minigame_1012_incorrect_118", 0, 3, 11130301, 6, "難しいわね…");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1303, 0, 0.0, 1, 4, 0, "vo_minigame_1012_incorrect_119", 0, 4, 11130302, 0, "難易度高すぎね…");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1304, 0, 0.0, 1, 2, 0, "vo_minigame_1012_incorrect_123", 0, 2, 11130401, 0, "忘れちゃダメよ？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1305, 0, 0.0, 1, 1, 0, "vo_minigame_1012_incorrect_126", 0, 1, 11130501, 0, "全部が間違いじゃないわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 3.18, 1, 7, 1, "vo_minigame_1012_result_1000", 10, 8, 11300101, 4, "フフ、全問正解よ！\nちゃんと勉強してるみたいで\n感心だわ♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 3.33, 1, 8, 1, "vo_minigame_1012_result_1001", 10, 7, 11300102, 10, "すごいじゃない…全問正解よ！\nま、当然といや当然よね～\nだってあたしが\n教えてやってんだから♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 5.41, 1, 8, 1, "vo_minigame_1012_result_1002", 10, 1, 11300103, 10, "全問正解！　パチパチパチ～♪\nこの難易度はもう完璧じゃない？\n次はもっと難しい問題に挑戦よ！\nあんたならできるって！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 8.11, 1, 5, 2, "vo_minigame_1012_result_1003", 10, 8, 11300104, 10, "へえ…難しい問題を選んだのに\n全問正解できてるじゃない！！\nちょっとあんたすごすぎだわ…！\nパーフェクトよパーフェクト！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 1.31, 1, 10, 2, "vo_minigame_1012_result_1004", 10, 5, 11300105, 0, "まる…まる…全部まる！\n難しい問題なのに全問正解よ…！\n驚いた…あんたいつの間に、\nこんなに勉強してたのよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 4.93, 1, 9, 2, "vo_minigame_1012_result_1005", 10, 8, 11300106, 0, "ここまで完璧に正解されちゃうと\nちょっと悔しいわね…！\nけど素直に褒めてやるわ！\nえらい、えらい、えら～い！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 2.99, 1, 5, 3, "vo_minigame_1012_result_1006", 10, 8, 11300107, 4, "すごい…あんたパーフェクトよ！\nこのままいけば次の試験、\n学年一位も夢じゃないかもね！\n楽しみだわ～♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 8.37, 1, 8, 3, "vo_minigame_1012_result_1007", 10, 7, 11300108, 4, "満点よ！　フフ、もうあんたに\n教えることはなにもないわ…！\n逆にあたしがあんたに教わりたい\nくらいよ！　…ね、先生♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 5.32, 1, 7, 3, "vo_minigame_1012_result_1008", 10, 5, 11300109, 8, "全・問・正・解！\n超難問揃いなのにすごいわね…！\nもしかしてだけど、\nあんたって天才！？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 7, 4.77, 1, 7, 1, "vo_minigame_1012_result_1009", 9, 1, 11300110, 4, "お、かなりいい点数ね～！\nあたしも教えがいがあるわ♪\nさ、まだまだ勉強するわよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 7, 2.97, 1, 8, 1, "vo_minigame_1012_result_1010", 9, 7, 11300111, 4, "うん、いい感じで点取れてるわ！\nこの調子で次は、\n満点を見せてほしいわね！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 7, 3.47, 1, 5, 1, "vo_minigame_1012_result_1011", 9, 1, 11300112, 0, "あ～惜しい！\nもうちょっとで満点じゃない！\n次はパーフェクトいけるわ！\n頑張りましょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 7, 5.32, 1, 8, 2, "vo_minigame_1012_result_1012", 9, 7, 11300113, 4, "すごい、かなりできてるわよ！\n難しい問題なのにやるじゃない！\nあとは目指せ、満点ね！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 7, 6.49, 1, 8, 2, "vo_minigame_1012_result_1013", 9, 7, 11300114, 10, "うん、かなりいい感じよ！\nあんたには赤点の心配なんて\nまーったくなさそうね♪\nでも勉強はやめさせないけど！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 7, 3.56, 1, 5, 2, "vo_minigame_1012_result_1014", 9, 1, 11300115, 0, "あーあとちょっとで\n全問正解だったのに！\n難しい問題だけどあんたなら\n次は満点狙えるわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 7, 5.67, 1, 8, 3, "vo_minigame_1012_result_1015", 9, 1, 11300116, 10, "うん、ほとんど正解よ！\nこんな難しい問題なのに、\nすごいじゃない！\nやっぱりあんた只者じゃないわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 7, 2.85, 1, 7, 3, "vo_minigame_1012_result_1016", 9, 1, 11300117, 10, "着実に成長してるって感じね？\nあんたならこの難問でも、\nいつか満点取れちゃうかも…！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 7, 3.88, 1, 5, 3, "vo_minigame_1012_result_1017", 9, 1, 11300118, 0, "うわー惜しいわね！\nもうちょっとで満点よ？\nま、あたしでも悩む難問だから、\nこの点数は胸を張っていいわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 4, 4.12, 1, 3, 1, "vo_minigame_1012_result_1018", 6, 1, 11300119, 0, "正解率は半分くらいか～\n悪くはないんだけど、あんたなら\nこんなもんじゃないでしょ？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 4, 4.34, 1, 9, 1, "vo_minigame_1012_result_1019", 6, 1, 11300120, 0, "んーはっきり言っちゃうと\n中途半端な点数ね…\nまあいいわ！こっからガンガン\n点数上げていくわよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 4, 3.15, 1, 3, 1, "vo_minigame_1012_result_1020", 6, 1, 11300121, 0, "う～ん、正直物足りない点数ね！\nあんたには期待してんだから、\nもっと頑張んなさい！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 4, 5.3, 1, 9, 2, "vo_minigame_1012_result_1021", 6, 1, 11300122, 0, "半分くらいの正解率か\n難しい問題だから仕方ないわね…\nでもあんたはもっとできる！\nだってあたしがついてんのよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 4, 2.55, 1, 8, 2, "vo_minigame_1012_result_1022", 6, 1, 11300123, 0, "うん、そこそこできんじゃない！\n頑張って勉強して\nさらに上を目指しましょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 4, 4.19, 1, 1, 2, "vo_minigame_1012_result_1023", 6, 7, 11300124, 0, "難問なのにこの正解率は\nよくやってる方よね！\nでもこんなところで\n満足してんじゃないわよ！？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 4, 3.43, 1, 7, 3, "vo_minigame_1012_result_1024", 6, 1, 11300125, 0, "難問なのに半分くらい正解\nできてんじゃない♪\nこの調子でもっと学力\n上げていきましょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 4, 0.0, 1, 1, 3, "vo_minigame_1012_result_1025", 6, 1, 11300126, 0, "よし、平均点ってとこね！\nちゃんと勉強してるみたいで\n安心したわ～♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 4, 3.72, 1, 8, 3, "vo_minigame_1012_result_1026", 6, 7, 11300127, 0, "難問揃いでこの正解率は\n大したもんよ！\nま、もっといい点取りたいんなら\n勉強、付き合ったげるわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 3.5, 1, 3, 1, "vo_minigame_1012_result_1027", 3, 2, 11300128, 1, "なるほど…\nこれは教えがいがあるわね\nビシバシ鍛えてやるから\n覚悟しなさい！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 3.25, 1, 4, 1, "vo_minigame_1012_result_1028", 3, 2, 11300129, 1, "ちょっとあんた、\n全然できてないじゃない！\n…まさかこれが本気だなんて\n言わないわよね～？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 4.62, 1, 3, 1, "vo_minigame_1012_result_1029", 3, 2, 11300130, 0, "うーん……適当に答えても\nこれくらい正解できるわよ？\nちょっと本腰入れて\n教えないとね……！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 4.5, 1, 9, 2, "vo_minigame_1012_result_1030", 3, 1, 11300131, 0, "…ま、まあこの問題は\nあんたには難しすぎたのかもね\nちょっとずつでいいから、\nレベルアップしていきましょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 0.01, 1, 3, 2, "vo_minigame_1012_result_1031", 3, 3, 11300132, 9, "んー結構ミスっちゃってるわね…\nこのまま続けるのもいいけど、\n簡単な問題からやり直すのも\nありかもよ～？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 0.01, 1, 9, 2, "vo_minigame_1012_result_1032", 3, 9, 11300133, 9, "あらら、あんたにはちょっと\n難しすぎたかしら…？\nもう一回やり直しましょうか！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 0.01, 1, 3, 3, "vo_minigame_1012_result_1033", 3, 3, 11300134, 6, "うーん、残念な結果ね…\n超難問だから仕方ないけど\n無理せず簡単な問題から挑戦\nしてもいいかもよ？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 2.97, 1, 3, 3, "vo_minigame_1012_result_1034", 3, 9, 11300135, 0, "正解率はかなり悪いわね…\nまあ難しい問題だもんね…！\nそのチャレンジ精神は買うわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 3.1, 1, 3, 3, "vo_minigame_1012_result_1035", 3, 1, 11300136, 0, "なんとか０点は免れたわね…\n難問揃いだけど、\nもっと頑張っていきましょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 4.31, 1, 6, 1, "vo_minigame_1012_result_1036", 0, 2, 11300137, 1, "…あんたさ、０点なんて\n逆に取るの難しいわよ！？\nまさか狙ったわけじゃ\nないでしょーね～！？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 0.1, 1, 2, 1, "vo_minigame_1012_result_1037", 0, 2, 11300138, 1, "０点って…\nあんたふざけてんの！？\nちゃんとやらないなら\n電撃魔法くらわせるわよ！？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 4.23, 1, 9, 1, "vo_minigame_1012_result_1038", 0, 3, 11300139, 9, "もしかしたらあんたは\n勉強向いてないのかもね…\n…勉強だけがすべてじゃないわ\n違うとこで頑張りましょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 4.38, 1, 3, 2, "vo_minigame_1012_result_1039", 0, 2, 11300140, 0, "怒んないから正直に言って？\n…ふざけて答えたでしょ？\nほら、正直に\n言・い・な・さ・い？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 3.58, 1, 8, 2, "vo_minigame_1012_result_1040", 0, 2, 11300141, 0, "あんたの点数は～～…\n…はい！　０てーん！！\n…って、ふざけんなーー！！！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 2.02, 1, 4, 2, "vo_minigame_1012_result_1041", 0, 2, 11300142, 1, "０点ってどういうこと！？\nいやあんた、逆にすごいわよ！？\n目つぶってやったとしても\n１点は取れるから！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 5.53, 1, 9, 3, "vo_minigame_1012_result_1042", 0, 1, 11300143, 9, "あちゃー……残念だけど０点よ\nちょっと難しすぎたかもねー…\n…ま、こんなこともあるわ！\n気を落とさなくていいわよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 4.4, 1, 3, 3, "vo_minigame_1012_result_1043", 0, 1, 11300144, 9, "かなりの難問とはいえ、\n０点はちょっと寂しいわね…\nでもま、逆に考えるのよ！\nあんたには伸びしろしかないわ！");
