INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 20, 3.74, 2, 7, 1, "vo_minigame_1012_result_1045", -1, 1, 12300101, 10, "はい、よくできました！\n基礎はもう完璧ね！\n次はもっと難しい問題にも\nチャレンジしちゃいなさいよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 20, 3.85, 2, 1, 1, "vo_minigame_1012_result_1046", -1, 9, 12300102, 0, "なによあんた、走り出したペンが\n止まらないって感じ？\nったくシンプルにすごいじゃない\n花丸あげるわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 20, 0.01, 2, 5, 1, "vo_minigame_1012_result_1047", -1, 5, 12300103, 8, "すごい点数ね…！\nあんた勉強してないとか言って\nホントはめちゃくちゃやってる\nパターンのやつね！？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 20, 2.86, 2, 8, 2, "vo_minigame_1012_result_1048", -1, 7, 12300104, 4, "勉強の成果、\nちゃんとでてんじゃない！\nあたしもあんたの先生として、\n鼻が高いわ～♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 20, 2.02, 2, 5, 2, "vo_minigame_1012_result_1049", -1, 3, 12300105, 9, "オッケー！　もう十分よ！\nこれ以上でき過ぎちゃったら、\nあたしが教える必要なくなるわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 20, 4.46, 2, 5, 2, "vo_minigame_1012_result_1050", -1, 1, 12300106, 0, "難しい問題を選んだつもりなのに\nすごい正解数ね…！\nでもまだ上がある…\n次は最難関に挑戦よ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 20, 6.85, 2, 5, 3, "vo_minigame_1012_result_1051", -1, 4, 12300107, 7, "すごいすごいとは思ってたけど、\nあんた勉強も完璧なの…？\nそりゃみんなあんたに惚れ…\nや、な、なんでもない！！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 20, 3.79, 2, 5, 3, "vo_minigame_1012_result_1052", -1, 9, 12300108, 0, "この問題、あたしでも悩む\n超難問なのに…\nふふっ、もう褒めるしかないわ！\n大変よくできました！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 20, 0.01, 2, 4, 3, "vo_minigame_1012_result_1053", -1, 4, 12300109, 7, "別に顔赤くなんてなってない！\n頭がいい人が好きとか…\nかっこいいとか…\n…思ってないからね！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 20, 0.0, 2, 5, 1, "vo_minigame_1012_result_1054", -1, 5, 12300110, 0, "スピードも正確さも完璧…\n文句なしの満点だわ！\nあんた将来、とんでもない人に\nなっちゃうんじゃない！？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 20, 0.0, 2, 5, 2, "vo_minigame_1012_result_1054", -1, 5, 12300112, 0, "スピードも正確さも完璧…\n文句なしの満点だわ！\nあんた将来、とんでもない人に\nなっちゃうんじゃない！？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 20, 0.0, 2, 5, 3, "vo_minigame_1012_result_1054", -1, 5, 12300114, 0, "スピードも正確さも完璧…\n文句なしの満点だわ！\nあんた将来、とんでもない人に\nなっちゃうんじゃない！？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 15, 3.0, 2, 5, 1, "vo_minigame_1012_result_1056", 19, 7, 12300116, 10, "おお～かなり正解できてるわね！\nこの調子でもっとすごい点\n目指しちゃうわよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 15, 0.01, 2, 8, 1, "vo_minigame_1012_result_1057", 19, 8, 12300117, 10, "うん、バッチリいい感じよ！\nちゃんと勉強してるみたいで\n関心関心♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 15, 4.01, 2, 5, 1, "vo_minigame_1012_result_1058", 19, 8, 12300118, 0, "え、こんなにいい点取れたのに\nまだ満足してないの？\nなによその向上心…\nいいじゃない！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 15, 2.83, 2, 8, 2, "vo_minigame_1012_result_1059", 19, 7, 12300119, 10, "スピードも正解数もいい感じよ！\nねえねえ、この調子で\nてっぺん目指しちゃう？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 15, 0.0, 2, 10, 2, "vo_minigame_1012_result_1060", 19, 10, 12300120, 0, "この難易度でも\nスラスラ答えちゃうなんて…\nあんたって\nほんとすごいやつよね…！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 15, 3.66, 2, 8, 2, "vo_minigame_1012_result_1061", 19, 7, 12300121, 4, "これだけ正解できたら\n勉強も楽しいわよね♪\nさ、まだまだ続けるわよ～！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 15, 3.28, 2, 5, 3, "vo_minigame_1012_result_1062", 19, 8, 12300122, 0, "あんた、この成績\nまぐれじゃないわよね…！\nこれだけできたら\n大したもんだわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 15, 2.7, 2, 8, 3, "vo_minigame_1012_result_1063", 19, 1, 12300123, 0, "すごい！　とってもいい成績よ！\nこの難問も、あんたにかかりゃ\nイチコロってやつ？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 15, 3.98, 2, 5, 3, "vo_minigame_1012_result_1064", 19, 9, 12300124, 9, "あんた…もしかして\nあたしより点数いいかも？\nあ、あたしもあんたを見習って\n勉強しないとね…！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 2.51, 2, 7, 1, "vo_minigame_1012_result_1067", 14, 1, 12300131, 0, "うん、なかなかいい点数よ！\nでもまだまだ頑張れるわよね？\nはい、次いきましょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 4.16, 2, 1, 1, "vo_minigame_1012_result_1068", 14, 7, 12300132, 0, "十分優秀な成績だけど\nあんたならもっとできる！\nさ、頑張って勉強するわよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 2.07, 2, 8, 1, "vo_minigame_1012_result_1069", 14, 7, 12300133, 0, "うん、いい感じね！\nこの調子で少しずつ、\n正解数を増やしてくわよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 3.51, 2, 8, 2, "vo_minigame_1012_result_1070", 14, 1, 12300134, 0, "難問揃いなのに、\nけっこーいい感じじゃない！\nちゃんとできてるから\n自信もっていいわよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 0.0, 2, 1, 2, "vo_minigame_1012_result_1071", 14, 1, 12300135, 0, "難しい問題でも基礎は大事よ！\nこの調子でどんどん\n点数上げていきましょう！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 4.3, 2, 1, 2, "vo_minigame_1012_result_1072", 14, 7, 12300136, 0, "10問以上取れてるわね！\nえ、まだ物足りない？\nフフ、じゃあもっと上\n目指しちゃう？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 4.47, 2, 8, 3, "vo_minigame_1012_result_1073", 14, 7, 12300137, 0, "うん、この難問でこの点数は\n十分すぎる出来よね！\nま、あんたならもっといい点\n目指しちゃうんだろうけど♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 3.68, 2, 8, 3, "vo_minigame_1012_result_1074", 14, 9, 12300138, 0, "はいお疲れ～\nなかなか良い点数じゃない\n…あたしも勉強しないとね！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 3.34, 2, 5, 3, "vo_minigame_1012_result_1075", 14, 1, 12300139, 0, "おお～10問以上\n正解してんじゃない！\nあんたやっぱり\nただ者じゃないわね～");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 6.58, 2, 1, 1, "vo_minigame_1012_result_1077", 14, 8, 12300141, 0, "うん正解率は申し分なしね！\nあとはもっと早く解ければ\nもっと点数は伸びてくわよ！\nこの調子で頑張っていきましょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 6.58, 2, 1, 2, "vo_minigame_1012_result_1077", 14, 8, 12300143, 0, "うん正解率は申し分なしね！\nあとはもっと早く解ければ\nもっと点数は伸びてくわよ！\nこの調子で頑張っていきましょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 10, 6.58, 2, 1, 3, "vo_minigame_1012_result_1077", 14, 8, 12300145, 0, "うん正解率は申し分なしね！\nあとはもっと早く解ければ\nもっと点数は伸びてくわよ！\nこの調子で頑張っていきましょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 5, 4.24, 2, 1, 1, "vo_minigame_1012_result_1078", 9, 7, 12300146, 0, "ふ～ん、まあまあの出来だわ\n悪くはないんだけど…あんたには\nもっともっと期待してるわ～");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 5, 4.74, 2, 7, 1, "vo_minigame_1012_result_1079", 9, 1, 12300147, 0, "うん、頑張ったけど…\n正直もっと正解できるかもね～？\nこんなのあんたには通過点！\nさらに良い点目指してみない？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 5, 0.0, 2, 1, 1, "vo_minigame_1012_result_1080", 9, 1, 12300148, 0, "まあまあな点数だけど、\n自分的に手ごたえはどう？\nダメだって思ってんなら、\nまだまだ伸びる余地ありね！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 5, 2.21, 2, 8, 2, "vo_minigame_1012_result_1081", 9, 1, 12300149, 0, "うん、中々の出来ね！\nでもあんたはもっといい点\n取れるはずよ！\nもっと頑張りましょうか！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 5, 2.46, 2, 3, 2, "vo_minigame_1012_result_1082", 9, 1, 12300150, 0, "ん～はっきり言って微妙ね！\nま、難しい問題だし、\n勉強すれば\n点数は上がっていくと思うわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 5, 2.94, 2, 3, 2, "vo_minigame_1012_result_1083", 9, 1, 12300151, 0, "ん～…\n10点には届かなかったか～\n次は10点越え目指して\n頑張ってみない？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 5, 4.19, 2, 7, 3, "vo_minigame_1012_result_1084", 9, 1, 12300152, 0, "はいお疲れ～\n点数的にはまあまあってとこね！\nま、超難問だし頑張ったわよ");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 5, 0.0, 2, 1, 3, "vo_minigame_1012_result_1085", 9, 1, 12300153, 0, "うん、かなり難しい問題なのに\n最後までやり遂げたわね\n次はもっといい点目指してみる？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 5, 2.63, 2, 3, 3, "vo_minigame_1012_result_1086", 9, 1, 12300154, 0, "ちょっとミスが多かったかもね～\nでも間違えた所は復習して\n次は正解するわよー！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 5.53, 2, 3, 1, "vo_minigame_1012_result_1087", 4, 1, 12300155, 0, "あら…あんまり良くない点数ね～\nどうしたの、調子でも悪かった？\n次はもっと頑張りましょうか");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 0.01, 2, 3, 1, "vo_minigame_1012_result_1088", 4, 3, 12300156, 9, "ん～…正解数は\n物足りないわね～\nもうちょっと勉強の時間\n増やしちゃおっか？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 4.15, 2, 3, 1, "vo_minigame_1012_result_1089", 4, 1, 12300157, 3, "ん～…あんたならもうちょと\nいい点取れんでしょ～？\nもっと頑張んなさいよ\n期待してやってんだからさ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 0.01, 2, 9, 2, "vo_minigame_1012_result_1090", 4, 9, 12300158, 9, "ん～今のあんたには、\nこの問題は難しかったかしら…\n難易度下げてチャレンジするのも\nありかもね～？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 5.37, 2, 3, 2, "vo_minigame_1012_result_1091", 4, 1, 12300159, 0, "あんまり出来は良くないわね～\n難しい問題だししょうがないけど\n次はもっと頑張ってほしいわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 1.44, 2, 3, 2, "vo_minigame_1012_result_1092", 4, 1, 12300160, 0, "なるほど…\nちょっと苦手な問題が多かった？\nもう一度チャレンジ\nしてみましょうか～");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 0.0, 2, 3, 3, "vo_minigame_1012_result_1093", 4, 3, 12300161, 0, "んん～…問題が難しすぎた？\n無理に難しい問題続けるより、\n難易度下げた方が\n勉強の効率良いかもよ～？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 2.91, 2, 3, 3, "vo_minigame_1012_result_1094", 4, 9, 12300162, 3, "…あんまり点数取れなかったわね\nこれはあたしにも難しい問題だし\nそう落ち込まなくても大丈夫！\n次頑張りましょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 1, 2.61, 2, 5, 3, "vo_minigame_1012_result_1095", 4, 1, 12300163, 0, "ごめん、ちょっと難しすぎた？\nもう一度チャレンジするも良し、\n難易度を下げるも良し、\nあんたがやる気なら付き合うわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 3.63, 2, 4, 1, "vo_minigame_1012_result_1096", 0, 2, 12300164, 1, "ちょっとあんた…\nやる気ないわよね～！？\n次こんな点数取ったら\n怒るわよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 4.16, 2, 6, 1, "vo_minigame_1012_result_1097", 0, 2, 12300165, 1, "はあ…自分で何点取ったか\n分かってるわよね～…？\n０点よ０点！　舐めてんの！？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 0.01, 2, 3, 1, "vo_minigame_1012_result_1098", 0, 3, 12300166, 6, "うう～頭痛い…\nあんたのせいよ！\nなに０点って！\nはあ、このままじゃ赤点よ～…");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 5.75, 2, 6, 2, "vo_minigame_1012_result_1099", 0, 2, 12300167, 0, "ねえ、あんた本気でやったの？\nまさか適当にやるわけないわよね\n…分かった、\nもう一回チャレンジするのよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 5.64, 2, 4, 2, "vo_minigame_1012_result_1100", 0, 2, 12300168, 1, "あ…あんた、０点よ０点…！\nあたしの教え方が悪かった…？\n…燃えてきたわ！\n絶対あんたの学力上げてやる！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 5.73, 2, 8, 2, "vo_minigame_1012_result_1101", 0, 4, 12300169, 8, "ちょっと待って採点ミスかも…\n…いや合ってるわね。はい０点\n…って０点！？\nふざけんなーー！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 5.32, 2, 5, 3, "vo_minigame_1012_result_1102", 0, 3, 12300170, 1, "あらら…０点よ\nま、難しい問題だしね…\n…つっても０点は無いわ！\n一問くらい正解しなさいよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 2.37, 2, 3, 3, "vo_minigame_1012_result_1103", 0, 9, 12300171, 9, "残念だけど０点よ\nま、まあ前向きにとらえるなら、\n今が底よ！　どん底！\nあとは上がってくだけね！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 3001, 0, 4.25, 2, 9, 3, "vo_minigame_1012_result_1104", 0, 1, 12300172, 3, "…かなり出来が悪いわね\n一旦休憩しましょうか？\nリフレッシュして頭切り替えて\nもう一度頑張りましょう！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1001, 0, 0.0, 3, 7, 0, "vo_minigame_1012_gamestart_100", 0, 7, 13100101, 0, "さ、勉強を始めるわよ");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1001, 0, 0.0, 3, 1, 0, "vo_minigame_1012_gamestart_101", 0, 1, 13100102, 0, "よし、勉強の成果を見てやるわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1001, 0, 1.82, 3, 1, 0, "vo_minigame_1012_gamestart_102", 0, 7, 13100103, 0, "じゃあ試験するわよ。はい教科書閉じて！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1002, 3, 0.01, 3, 8, 0, "vo_minigame_1012_gamestart_103", -1, 8, 13100201, 4, "やる気マンマンじゃない！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1002, 3, 0.0, 3, 1, 0, "vo_minigame_1012_gamestart_104", -1, 1, 13100202, 0, "よし、じゃあもう一回やるわよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1003, 1, 0.0, 3, 0, 0, "vo_minigame_1012_gamestart_105", 1, 0, 13100301, 0, "普通の難易度よ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1003, 1, 0.0, 3, 7, 0, "vo_minigame_1012_gamestart_106", 1, 7, 13100302, 0, "まずは基本からね！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1003, 2, 0.0, 3, 10, 0, "vo_minigame_1012_gamestart_107", 2, 10, 13100303, 0, "難しい問題に挑戦するのね！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1003, 2, 0.67, 3, 1, 0, "vo_minigame_1012_gamestart_108", 2, 8, 13100304, 0, "よし、あんたならできるわ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1003, 3, 0.0, 3, 5, 0, "vo_minigame_1012_gamestart_109", 3, 5, 13100305, 0, "あたしでも手こずる難問揃いよ…！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1003, 3, 0.0, 3, 2, 0, "vo_minigame_1012_gamestart_110", 3, 2, 13100306, 0, "激ムズだけど頑張んなさい！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1004, 0, 0.0, 3, 7, 0, "vo_minigame_1012_gamestart_111", 0, 7, 13100401, 0, "鉄は熱いうちに打て、\n…ってね♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1004, 0, 0.0, 3, 1, 0, "vo_minigame_1012_gamestart_112", 0, 1, 13100402, 0, "よし、もっぺんやるわよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1005, 0, 0.0, 3, 9, 0, "vo_minigame_1012_gamestart_113", 0, 9, 13100501, 0, "スズナもちゃんと勉強してるみたいね～");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1005, 0, 0.0, 3, 3, 0, "vo_minigame_1012_gamestart_114", 0, 3, 13100502, 0, "あんたがスズナの\n先生？　…ふーん");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1101, 0, 0.0, 3, 1, 0, "vo_minigame_1012_start_100", 0, 1, 13110101, 0, "問題！");
