INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1104, 3, 0.0, 3, 0, 0, "vo_minigame_1012_start_122", 3, 0, 13110408, 0, "答えは複数あるわ！");
