INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1105, 0, 0.0, 3, 1, 0, "vo_minigame_1012_start_127", 0, 1, 13110501, 0, "これはできてたわね");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1105, 0, 0.0, 3, 10, 0, "vo_minigame_1012_start_128", 0, 10, 13110502, 0, "見覚えのある問題ね");
