INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (1, 1106, 0, 0.0, 3, 3, 0, "vo_minigame_1012_start_125", 0, 3, 13110602, 0, "これまだ正解してないわ");
