INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 1304, 0, 0.0, 1, 6, 0, "vo_minigame_1012_incorrect_223", 0, 6, 21130401, 0, "あれ、違った…？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 1305, 0, 0.0, 1, 8, 0, "vo_minigame_1012_incorrect_226", 0, 8, 21130501, 0, "あとちょいだったね…！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 3.32, 1, 6, 1, "vo_minigame_1012_result_2000", 10, 0, 21300101, 0, "すご、全部〇じゃん…！\nこの調子で教えてくれたら\nうちも頭よくなりそー！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 6.5, 1, 6, 1, "vo_minigame_1012_result_2001", 10, 2, 21300102, 3, "え、〇しかなかった…？\n満点ってほんとにあるんだ…\nヒデサイマジすごい…！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 3.1, 1, 3, 1, "vo_minigame_1012_result_2002", 10, 6, 21300103, 5, "満点じゃん！　やりー！\nもしかしてヒデサイには\n簡単過ぎた感じ？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 2.06, 1, 3, 2, "vo_minigame_1012_result_2003", 10, 2, 21300104, 11, "ビシッと決まったね！\nヒデサイ、ベンキョー\n教えてくれてありがとー♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 4.45, 1, 3, 2, "vo_minigame_1012_result_2004", 10, 7, 21300105, 0, "ムズい問題もぜーんぶ正解！\n激アツじゃん！\nヒデサイ、頭よすぎ～");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 0.01, 1, 2, 2, "vo_minigame_1012_result_2005", 10, 2, 21300106, 11, "きゃはっ、満点じゃん！\n一緒にベンキョーしてる\nうちまでいい気分！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 6.64, 1, 2, 3, "vo_minigame_1012_result_2006", 10, 3, 21300107, 11, "ヒデサイ、満点パーフェクト！\nこれで、もーサイツヨだね！\nそれっ、ハイタッチ～！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 0.0, 1, 6, 3, "vo_minigame_1012_result_2007", 10, 6, 21300108, 0, "カンペキ過ぎて\nまぶしぃんですけど！\n〇しかないってどゆこと！？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 5.76, 1, 6, 3, "vo_minigame_1012_result_2008", 10, 7, 21300109, 0, "おにムズでも満点じゃん…！\nヒデサイセンセーマジすごい！\nこれからも頼りにしてるよ～");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 7, 0.0, 1, 6, 1, "vo_minigame_1012_result_2009", 9, 6, 21300110, 0, "ヒデサイ、もしかして\nよゆーな感じ？\n正解しまくりじゃん！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 7, 2.59, 1, 2, 1, "vo_minigame_1012_result_2010", 9, 7, 21300111, 0, "〇いっぱいで、わろ～\nてかヒデサイ教えるのうまっ！\nめちゃわかりやすかったよ♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 7, 4.09, 1, 2, 1, "vo_minigame_1012_result_2011", 9, 3, 21300112, 11, "これだけ〇あったら、\nめちゃ気持ちいいね♪\n次は満点取っちゃおー！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 7, 2.47, 1, 2, 2, "vo_minigame_1012_result_2012", 9, 3, 21300113, 0, "満点まで、もーすぐじゃん！\nさっすがヒデサイ！\nバイブス上がってきた～");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 7, 0.01, 1, 3, 2, "vo_minigame_1012_result_2013", 9, 3, 21300114, 11, "きゃはっ、めちゃ解けてる～\nもー次は満点っしょ！\nテンアゲしてきたね♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 7, 0.0, 1, 2, 2, "vo_minigame_1012_result_2014", 9, 2, 21300115, 0, "ヒデサイのおかげで\nうちもちょっちベンキョー\nわかってきたかも！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 7, 3.45, 1, 6, 3, "vo_minigame_1012_result_2015", 9, 2, 21300116, 0, "おにムズ問題も\n〇ばっかじゃん…！\nヒデサイ、マジ心強い！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 7, 0.0, 1, 3, 3, "vo_minigame_1012_result_2016", 9, 3, 21300117, 0, "ヒデサイセンセーに\n追いつけ追い越せ！\nうちもがんばる～！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 7, 4.0, 1, 2, 3, "vo_minigame_1012_result_2017", 9, 3, 21300118, 0, "おにムズ問題も\nあとちょいで満点じゃん！\nもーここまできたら\nやるしかないっしょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 4, 0.92, 1, 6, 1, "vo_minigame_1012_result_2018", 6, 0, 21300119, 0, "お！　あと半分だし\nうちも、もうちっと\nがんばってみるね！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 4, 4.36, 1, 0, 1, "vo_minigame_1012_result_2019", 6, 3, 21300120, 0, "まだイミフな問題あるけど\n悪くないよね？\nバイブス上がってきたし\n次もっとイケんじゃない？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 4, 2.35, 1, 6, 1, "vo_minigame_1012_result_2020", 6, 2, 21300121, 0, "だいたい半分ぐらい？\nじゃあ、こっからだね！\n集中、集中！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 4, 2.13, 1, 0, 2, "vo_minigame_1012_result_2021", 6, 2, 21300122, 0, "これで半分ぐらい？\nよしっ、とりま赤点回避！\nやりー！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 4, 2.38, 1, 0, 2, "vo_minigame_1012_result_2022", 6, 2, 21300123, 0, "あともう半分だね！\nフレッフレッ、ヒデサイ！\nうちもがんばる～！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 4, 3.5, 1, 4, 2, "vo_minigame_1012_result_2023", 6, 0, 21300124, 0, "う～ん、やっぱムズいね\nでも、半分ぐらい〇だし\nイケそーな気するね！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 4, 2.25, 1, 0, 3, "vo_minigame_1012_result_2024", 6, 6, 21300125, 0, "だいたい半分正解？\nとゆーことは\nあと半分で満点じゃん！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 4, 2.14, 1, 3, 3, "vo_minigame_1012_result_2025", 6, 6, 21300126, 0, "やるじゃんヒデサイ！\nえ？　もっと上目指すの？\nじゃあうちもがんばる！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 4, 3.75, 1, 6, 3, "vo_minigame_1012_result_2026", 6, 2, 21300127, 0, "おにムズだったのに\n半分解けてる…！？\nヒデサイいい感じ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 2.53, 1, 4, 1, "vo_minigame_1012_result_2027", 3, 10, 21300128, 5, "おにムズだったね～\n…え？　これって簡単なの？\nえへへ、うそだ～？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 0.01, 1, 4, 1, "vo_minigame_1012_result_2028", 3, 4, 21300129, 9, "…ねーねー、ヒデサイ\nうちに合わせて\n悪い点取らなくていいんだよ？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 2.93, 1, 0, 1, "vo_minigame_1012_result_2029", 3, 3, 21300130, 0, "ウォーミングアップは\nこんなところで…\nヒデサイ、次は\n本気出しちゃおうよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 4.26, 1, 0, 2, "vo_minigame_1012_result_2030", 3, 3, 21300131, 4, "あ、ヒデサイ\nうちと点数おそろじゃん！\n一緒に赤点取っちゃおっか～♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 0.0, 1, 10, 2, "vo_minigame_1012_result_2031", 3, 10, 21300132, 0, "えーっと…\nもっかい教えてくれたら\n次はもうちょい\nイケる気するよっ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 4.98, 1, 9, 2, "vo_minigame_1012_result_2032", 3, 0, 21300133, 5, "うちもさっぱりだった～\nどこ間違えたんだろ…？\nもっかいベンキョーしてみる？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 0.01, 1, 4, 3, "vo_minigame_1012_result_2033", 3, 4, 21300134, 9, "おにムズ過ぎてマジさっぱり…\nどーしよ…\nヒデサイ、助けて～");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 0.01, 1, 4, 3, "vo_minigame_1012_result_2034", 3, 4, 21300135, 6, "赤点って感じ？\nう～ん…せっかくだし\nうちと一緒にがんばろ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 2.51, 1, 4, 3, "vo_minigame_1012_result_2035", 3, 10, 21300136, 11, "やっぱムズいね…\nでも０点じゃないし\nオーライっしょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 2.54, 1, 0, 1, "vo_minigame_1012_result_2036", 0, 6, 21300137, 0, "よし、結果は…\nって０ってマ！？\nヒデサイ、どーしちゃったの？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 4.08, 1, 2, 1, "vo_minigame_1012_result_2037", 0, 10, 21300138, 5, "ヒデサイ\nわざと０点取ったっしょ？\n違うの？　ほんとに～？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 3.41, 1, 6, 1, "vo_minigame_1012_result_2038", 0, 4, 21300139, 0, "ヒデサイ、０点だね…\nうちが代わりに\nベンキョー教えてあげよっか…？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 4.1, 1, 10, 2, "vo_minigame_1012_result_2039", 0, 8, 21300140, 0, "んーっと…\nぜんぜんわかんなかった！\nでも、ベンキョーって\nいつもそーだよね！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 5.8, 1, 6, 2, "vo_minigame_1012_result_2040", 0, 2, 21300141, 4, "これ、うちら習ったっけ？\nヒデサイも覚えてない感じ？\nじゃあ仕方ないっしょ！\n次いこ次！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 4.6, 1, 10, 2, "vo_minigame_1012_result_2041", 0, 8, 21300142, 3, "ねねね、全部×って\nこれはこれでレアなんじゃ？\n喜んじゃダメ？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 6.04, 1, 10, 3, "vo_minigame_1012_result_2042", 0, 2, 21300143, 0, "おにムズってのはわかった！\nこれも一歩前進…だよね？\n次がんばろーよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 1.92, 1, 9, 3, "vo_minigame_1012_result_2043", 0, 3, 21300144, 4, "０点…！　でもでも\nうちらバイブスは満点じゃん♪\nヒデサイ、もっかいやろ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 0.0, 1, 7, 3, "vo_minigame_1012_result_2044", 0, 7, 21300145, 0, "ヒデサイと同じ点数\nちょっちうれしーかも？\n一緒に０からがんばろーね！");
