INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 1701, 20000, 0.01, 2, 6, 0, "vo_minigame_1012_time_200", 30000, 6, 22170101, 3, "もー終わりそう！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 1701, 20000, 0.01, 2, 5, 0, "vo_minigame_1012_time_201", 30000, 5, 22170102, 9, "急がなきゃ…！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 20, 2.81, 2, 2, 1, "vo_minigame_1012_result_2045", -1, 3, 22300101, 4, "〇多すぎてわろ～\nスラスラ解いてくし\nまじカッコよかったよ♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 20, 2.31, 2, 3, 1, "vo_minigame_1012_result_2046", -1, 2, 22300102, 11, "点数イケイケじゃん！　\nもしかして、ヒデサイには\n簡単過ぎた感じ？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 20, 0.01, 2, 3, 1, "vo_minigame_1012_result_2047", -1, 3, 22300103, 11, "きゃはっ、もうバッチリだね♪\n他の問題も教えてほしーし\n次はムズいのいっちゃう？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 20, 4.33, 2, 6, 2, "vo_minigame_1012_result_2048", -1, 7, 22300104, 11, "ムズい問題なのに\n〇でいっぱいじゃん…！\nさっすが、ヒデサイセンセー！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 20, 5.73, 2, 6, 2, "vo_minigame_1012_result_2049", -1, 2, 22300105, 0, "一緒にベンキョー\nしてるだけなのに\nうちまで賢くなった気する…！\nマジありがとね");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 20, 0.01, 2, 6, 2, "vo_minigame_1012_result_2050", -1, 6, 22300106, 8, "これってムズい問題だよね？\nなんで簡単に解いてくの？\nヒデサイ、すごすぎ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 20, 4.02, 2, 6, 3, "vo_minigame_1012_result_2051", -1, 3, 22300107, 0, "おにムズなのに\n答えるの一瞬だったね…！\nヒデサイ、頭良すぎじゃん？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 20, 5.24, 2, 2, 3, "vo_minigame_1012_result_2052", -1, 3, 22300108, 11, "まる、まる、はなまる～\nきゃははっ、すごっ！\nさっすがヒデサイ！\nハイタッチー！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 20, 4.6, 2, 2, 3, "vo_minigame_1012_result_2053", -1, 3, 22300109, 4, "これだけ教えてもらったら\nもうテストもよゆーっしょ！\nヒデサイ、マジありがとね♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 20, 5.57, 2, 6, 1, "vo_minigame_1012_result_2054", -1, 10, 22300110, 0, "うちこんなの初めて見た…！\nヒデサイセンセー、神ってる！\nそだ、記念にこれ飾っとこうよ♪\nえ、それはちょっち恥ずかしい？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 20, 5.57, 2, 6, 2, "vo_minigame_1012_result_2054", -1, 10, 22300112, 0, "うちこんなの初めて見た…！\nヒデサイセンセー、神ってる！\nそだ、記念にこれ飾っとこうよ♪\nえ、それはちょっち恥ずかしい？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 20, 5.57, 2, 6, 3, "vo_minigame_1012_result_2054", -1, 10, 22300114, 0, "うちこんなの初めて見た…！\nヒデサイセンセー、神ってる！\nそだ、記念にこれ飾っとこうよ♪\nえ、それはちょっち恥ずかしい？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 15, 0.0, 2, 2, 1, "vo_minigame_1012_result_2056", 19, 2, 22300116, 0, "めちゃ問題あったのに\nバンバン答えてくし\n超頼もしかった！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 15, 5.23, 2, 6, 1, "vo_minigame_1012_result_2057", 19, 3, 22300117, 11, "おーさすがヒデサイ！\n〇の数も超ヒデサイだね♪\nイェーイ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 15, 3.23, 2, 3, 1, "vo_minigame_1012_result_2058", 19, 2, 22300118, 11, "ヒデサイ、〇でいっぱいじゃん♪\nうちも教えてもらったとこは\nけっこー覚えてきたかも？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 15, 6.0, 2, 3, 2, "vo_minigame_1012_result_2059", 19, 7, 22300119, 10, "アゲアゲな点数じゃん！\nとりま、どやっとく？\nせーの、どやぁ…！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 15, 0.0, 2, 7, 2, "vo_minigame_1012_result_2060", 19, 7, 22300120, 0, "ムズい問題も\nだんだん解けてくると\nたのしーね\nちょっち感動～");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 15, 0.0, 2, 6, 2, "vo_minigame_1012_result_2061", 19, 6, 22300121, 0, "たくさん解いても\nヒデサイは頭パンクしないの？\nスゴ…！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 15, 3.06, 2, 6, 3, "vo_minigame_1012_result_2062", 19, 2, 22300122, 3, "わわっ、〇ばっかり…！\nこの調子なら\n次は20に届くんじゃない？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 15, 5.74, 2, 6, 3, "vo_minigame_1012_result_2063", 19, 5, 22300123, 0, "15個以上〇って…！\nおにムズなのに、すごすぎ～\nうちもがんばらなきゃ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 15, 2.67, 2, 6, 3, "vo_minigame_1012_result_2064", 19, 3, 22300124, 0, "すっごい集中力…！\nもしかして、ヒデサイ\nおにムズ問題ほど\n燃える感じっしょ？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 0.0, 2, 3, 1, "vo_minigame_1012_result_2067", 14, 3, 22300131, 0, "きゃはっ、いい感じ！\nたくさん解けてるし\nベンキョーの成果\n…ってやつだね♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 0.0, 2, 2, 1, "vo_minigame_1012_result_2068", 14, 2, 22300132, 0, "10個以上〇だね♪\nヒデサイのおかげで\nうちも、ちょっち\n頭よくなったかな？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 2.28, 2, 10, 1, "vo_minigame_1012_result_2069", 14, 2, 22300133, 0, "けっこー解けたよね？\nやっぱ〇増えると\nバイブス上がる～");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 0.0, 2, 2, 2, "vo_minigame_1012_result_2070", 14, 2, 22300134, 0, "ベンキョーってあれだね\nわかった気すると\nまあまあたのしーかも！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 2.1, 2, 6, 2, "vo_minigame_1012_result_2071", 14, 2, 22300135, 0, "10個以上解けてる！？\nけっこーいいペースだよね？\nいい調子、いい調子～");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 2.13, 2, 2, 2, "vo_minigame_1012_result_2072", 14, 3, 22300136, 0, "けっこー解けてる！\nムズい問題もヒデサイと\n一緒なら怖くないね♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 0.0, 2, 7, 3, "vo_minigame_1012_result_2073", 14, 7, 22300137, 0, "おにムズ問題でも教えるの\n超やさしーし、マジ感謝！\n一緒にがんばろーね♪");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 0.0, 2, 6, 3, "vo_minigame_1012_result_2074", 14, 6, 22300138, 0, "おにムズなのに\n〇けっこーあるし\nヒデサイすごくない？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 10, 4.21, 2, 6, 3, "vo_minigame_1012_result_2075", 14, 5, 22300139, 0, "おにムズでこのペースは\nすごいんじゃ…？\nうちもがんばってついてくね！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 5, 1.94, 2, 0, 1, "vo_minigame_1012_result_2078", 9, 3, 22300146, 0, "悪くないよね？\nでもでも\nヒデサイとうちなら\nもっとできる気する！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 5, 2.28, 2, 4, 1, "vo_minigame_1012_result_2079", 9, 0, 22300147, 0, "もっと〇ほしーね…\n地道にやるしか\nないっぽいし\nもっかい教えてくれる？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 5, 0.0, 2, 4, 1, "vo_minigame_1012_result_2080", 9, 4, 22300148, 0, "ベンキョーしたけど\nわかんないとこばっか…\nヒデサイセンセー、助けて～");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 5, 2.67, 2, 4, 2, "vo_minigame_1012_result_2081", 9, 3, 22300149, 0, "やっぱムズかったね…\nでも次はもうちょい\nできそーな気がするよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 5, 4.68, 2, 10, 2, "vo_minigame_1012_result_2082", 9, 6, 22300150, 0, "問題ムズいし、この点数は\nありよりのありっしょ？\nえ、もっとできた感じ？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 5, 0.0, 2, 9, 2, "vo_minigame_1012_result_2083", 9, 9, 22300151, 0, "どこ間違ったんだろ？\nうちさっぱりだった…\nやっぱムズいだけあるね");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 5, 3.55, 2, 0, 3, "vo_minigame_1012_result_2084", 9, 3, 22300152, 0, "激ムズだけど\nやることは一緒だよね？\nうちもヒデサイについてくから\nコツコツがんばろ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 5, 2.51, 2, 4, 3, "vo_minigame_1012_result_2085", 9, 6, 22300153, 0, "やっぱおにムズだね…\nそだ、迷ったら\nヒント使うのも\nありよりのあり？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 5, 6.15, 2, 9, 3, "vo_minigame_1012_result_2086", 9, 5, 22300154, 0, "やっぱテストって\nなんとなくじゃ無理？\n覚えるしかないの？\nじゃあがんばるしかないね…");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 4.12, 2, 4, 1, "vo_minigame_1012_result_2087", 4, 9, 22300155, 6, "できたと思ったけど\nそーじゃなかった系？\nテストってマジきびしー…");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 0.01, 2, 4, 1, "vo_minigame_1012_result_2088", 4, 4, 22300156, 6, "うーん…さっぱり！\nでも簡単な問題なんだよね…？\nもっかいやってみる？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 5.28, 2, 0, 1, "vo_minigame_1012_result_2089", 4, 3, 22300157, 0, "うちらまだまだ\nベンキョーちうだし…\nこれからだよねっ？\nね、ヒデサイ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 2.89, 2, 0, 2, "vo_minigame_1012_result_2090", 4, 3, 22300158, 0, "ちょっとずつ覚えれば\nおーけーっしょ！\nうちと一緒に\nベンキョーだね！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 5.45, 2, 0, 2, "vo_minigame_1012_result_2091", 4, 7, 22300159, 0, "うちベンキョー苦手でも\nヒデサイとベンキョー\nするのは好き！　だから\nもっかい教えてくれる？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 4.29, 2, 4, 2, "vo_minigame_1012_result_2092", 4, 10, 22300160, 3, "覚えても、すぐ忘れるんだけど\nどしたらいい？\nあ、そーゆうとき\nフクシューする感じ？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 4.64, 2, 4, 3, "vo_minigame_1012_result_2093", 4, 8, 22300161, 6, "ムズ過ぎ！\n頭パンクするかと思った…！\nヒデサイ、うちの頭\nふぅふぅして～");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 3.14, 2, 9, 3, "vo_minigame_1012_result_2094", 4, 5, 22300162, 0, "おにムズ過ぎてテンサゲ～\nでもヒデサイがんばってるし\nうちもがんばる！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 1, 6.59, 2, 7, 3, "vo_minigame_1012_result_2095", 4, 4, 22300163, 0, "ヒデサイと同じ点数で\nちょっち安心したかも\n一緒にがんばろーね！\n置いてっちゃやだよ？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 0.0, 2, 3, 1, "vo_minigame_1012_result_2096", 0, 3, 22300164, 0, "…まあ、これより下はないし\n次は大逆転\n点数爆上がりっしょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 2.2, 2, 9, 1, "vo_minigame_1012_result_2097", 0, 10, 22300165, 5, "０点じゃん…\nそだ、次はえんぴつ転がして\n選ぶ作戦やってみる？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 0.01, 2, 4, 1, "vo_minigame_1012_result_2098", 0, 4, 22300166, 6, "考えるの無理な時あるよね…\nヒデサイもそーゆう\n感じだったの？");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 2.8, 2, 6, 2, "vo_minigame_1012_result_2099", 0, 2, 22300167, 3, "え、ヒデサイも０点？\nじゃあうちと一緒じゃん♪\nまあ焦んないで\nベンキョーしてこーよ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 3.22, 2, 9, 2, "vo_minigame_1012_result_2100", 0, 4, 22300168, 6, "むむむ～…０点…！\n覚えてもすぐ忘れちゃうし\nベンキョーってマジ大変");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 2.1, 2, 4, 2, "vo_minigame_1012_result_2101", 0, 0, 22300169, 11, "０点だね…\nでも、へーきへーき\nリベンジしたら、結果オーライ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 2.74, 2, 0, 3, "vo_minigame_1012_result_2102", 0, 2, 22300170, 3, "おやつ休憩して\nリベンジしよっ！\n甘いの食べたら、イケるっしょ！");
INSERT INTO `v1_b6627f909c194430e0243da55d75d66ac3b3842d647d27826bb1a2ff98711798` VALUES (2, 3001, 0, 3.0, 2, 6, 3, "vo_minigame_1012_result_2103", 0, 9, 22300171, 9, "ヒデサイでも\nおにムズな感じ？\nじゃあ、このテスト\n誰も解けなくない？");
